def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple[str, ...]] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int | None:
        if token.isascii() and token.isdigit():
            return int(token)
        return None

    for i, op in enumerate(ops):
        tokens = op.split(" ")
        verb = tokens[0]

        if verb == "open" and len(tokens) == 3:
            acc, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if amt is not None and acc not in balances:
                balances[acc] = amt
                history.append(("open", acc))
            else:
                rejected.append(i)

        elif verb == "deposit" and len(tokens) == 3:
            acc, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if amt is not None and amt > 0 and acc in balances:
                balances[acc] += amt
                history.append(("deposit", acc, amt))
            else:
                rejected.append(i)

        elif verb == "withdraw" and len(tokens) == 3:
            acc, raw_amt = tokens[1], tokens[2]
            amt = parse_amount(raw_amt)
            if (
                amt is not None
                and amt > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amt
            ):
                balances[acc] -= amt
                history.append(("withdraw", acc, amt))
            else:
                rejected.append(i)

        elif verb == "transfer" and len(tokens) == 4:
            src, dst, raw_amt = tokens[1], tokens[2], tokens[3]
            amt = parse_amount(raw_amt)
            if (
                amt is not None
                and amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(i)

        elif verb == "freeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(i)

        elif verb == "unfreeze" and len(tokens) == 2:
            acc = tokens[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(i)

        elif verb == "undo" and len(tokens) == 1:
            if not history:
                rejected.append(i)
                continue
            entry = history.pop()
            kind = entry[0]
            if kind == "open":
                del balances[entry[1]]
            elif kind == "deposit":
                balances[entry[1]] -= entry[2]
            elif kind == "withdraw":
                balances[entry[1]] += entry[2]
            elif kind == "transfer":
                balances[entry[1]] += entry[3]
                balances[entry[2]] -= entry[3]
            elif kind == "freeze":
                frozen.remove(entry[1])
            elif kind == "unfreeze":
                frozen.add(entry[1])

        else:
            rejected.append(i)

    return balances, rejected
